/**
 * QR Code Generator - Fast, lightweight, standalone (Zero dependencies)
 * High-reliability QR generator with dynamic Reed-Solomon error correction
 */
(function(window) {
    'use strict';

    // QR Code Model & Canvas Renderer
    function generateQRMatrix(text, ecl) {
        // Error correction levels: 'L', 'M', 'Q', 'H'
        var ecLevel = ecl || 'M';
        var qr = QrCode.encodeText(text, QrCode.Ecc[ecLevel]);
        return qr;
    }

    /* Core QR Generator implementation */
    var QrCode = (function() {
        function QrCode(version, errorCorrectionLevel, dataCodewords, msk) {
            this.version = version;
            this.errorCorrectionLevel = errorCorrectionLevel;
            this.size = version * 4 + 17;
            var modules = [];
            for (var y = 0; y < this.size; y++) {
                var row = [];
                for (var x = 0; x < this.size; x++) row.push(false);
                modules.push(row);
            }
            var isFunction = [];
            for (var y = 0; y < this.size; y++) {
                var row = [];
                for (var x = 0; x < this.size; x++) row.push(false);
                isFunction.push(row);
            }
            this.modules = modules;
            this.isFunction = isFunction;

            this.drawFunctionPatterns();
            var allCodewords = this.addEccAndInterleave(dataCodewords);
            this.drawCodewords(allCodewords);

            if (msk === -1) {
                var minPenalty = 1e9;
                var bestMask = 0;
                for (var i = 0; i < 8; i++) {
                    this.applyMask(i);
                    this.drawFormatBits(i);
                    var penalty = this.getPenaltyScore();
                    if (penalty < minPenalty) {
                        minPenalty = penalty;
                        bestMask = i;
                    }
                    this.applyMask(i); // revert
                }
                msk = bestMask;
            }
            this.mask = msk;
            this.applyMask(msk);
            this.drawFormatBits(msk);
        }

        QrCode.Ecc = {
            'L': { ordinal: 0, formatBits: 1 },
            'M': { ordinal: 1, formatBits: 0 },
            'Q': { ordinal: 2, formatBits: 3 },
            'H': { ordinal: 3, formatBits: 2 }
        };

        QrCode.encodeText = function(text, ecc) {
            var bytes = [];
            for (var i = 0; i < text.length; i++) {
                var c = text.charCodeAt(i);
                if (c < 128) bytes.push(c);
                else if (c < 2048) { bytes.push(192 | (c >> 6)); bytes.push(128 | (c & 63)); }
                else if (c < 65536) { bytes.push(224 | (c >> 12)); bytes.push(128 | ((c >> 6) & 63)); bytes.push(128 | (c & 63)); }
                else { bytes.push(240 | (c >> 18)); bytes.push(128 | ((c >> 12) & 63)); bytes.push(128 | ((c >> 6) & 63)); bytes.push(128 | (c & 63)); }
            }
            // Byte mode segment
            var seg = { mode: 4, numChars: bytes.length, data: bytes };
            for (var version = 1; version <= 40; version++) {
                var dataCapacityBits = QrCode.getNumDataCodewords(version, ecc) * 8;
                var charCountBits = (version < 10) ? 8 : 16;
                var headerBits = 4 + charCountBits;
                var totalBits = headerBits + bytes.length * 8;
                if (totalBits <= dataCapacityBits) {
                    var bb = [];
                    appendBits(4, 4, bb); // Mode: Byte
                    appendBits(bytes.length, charCountBits, bb);
                    for (var j = 0; j < bytes.length; j++) appendBits(bytes[j], 8, bb);
                    // Terminator
                    appendBits(0, Math.min(4, dataCapacityBits - bb.length), bb);
                    while (bb.length % 8 !== 0) bb.push(0);
                    // Pad bytes
                    var padBytes = [236, 17];
                    var padIdx = 0;
                    while (bb.length < dataCapacityBits) {
                        appendBits(padBytes[padIdx % 2], 8, bb);
                        padIdx++;
                    }
                    var dataCodewords = [];
                    for (var k = 0; k < bb.length; k += 8) {
                        var byteVal = 0;
                        for (var b = 0; b < 8; b++) byteVal = (byteVal << 1) | bb[k + b];
                        dataCodewords.push(byteVal);
                    }
                    return new QrCode(version, ecc, dataCodewords, -1);
                }
            }
            throw new Error('Data too long for QR Code');
        };

        function appendBits(val, len, arr) {
            for (var i = len - 1; i >= 0; i--) arr.push((val >>> i) & 1);
        }

        QrCode.prototype.getModule = function(x, y) {
            return (x >= 0 && x < this.size && y >= 0 && y < this.size) ? this.modules[y][x] : false;
        };

        QrCode.prototype.drawFunctionPatterns = function() {
            // Horizontal & vertical timing patterns
            for (var i = 0; i < this.size; i++) {
                this.setFunctionModule(6, i, i % 2 === 0);
                this.setFunctionModule(i, 6, i % 2 === 0);
            }
            // Finder patterns
            this.drawFinderPattern(3, 3);
            this.drawFinderPattern(this.size - 4, 3);
            this.drawFinderPattern(3, this.size - 4);

            // Alignment patterns
            var alignPositions = QrCode.getAlignmentPatternPositions(this.version);
            var numAlign = alignPositions.length;
            for (var y = 0; y < numAlign; y++) {
                for (var x = 0; x < numAlign; x++) {
                    if ((x === 0 && y === 0) || (x === 0 && y === numAlign - 1) || (x === numAlign - 1 && y === 0)) continue;
                    this.drawAlignmentPattern(alignPositions[x], alignPositions[y]);
                }
            }
            // Format dummy
            this.drawFormatBits(0);
            this.drawVersion();
        };

        QrCode.prototype.drawFinderPattern = function(x, y) {
            for (var dy = -4; dy <= 4; dy++) {
                for (var dx = -4; dx <= 4; dx++) {
                    var dist = Math.max(Math.abs(dx), Math.abs(dy));
                    var xx = x + dx, yy = y + dy;
                    if (xx >= 0 && xx < this.size && yy >= 0 && yy < this.size) {
                        this.setFunctionModule(xx, yy, dist !== 2 && dist !== 4);
                    }
                }
            }
        };

        QrCode.prototype.drawAlignmentPattern = function(x, y) {
            for (var dy = -2; dy <= 2; dy++) {
                for (var dx = -2; dx <= 2; dx++) {
                    this.setFunctionModule(x + dx, y + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
                }
            }
        };

        QrCode.prototype.setFunctionModule = function(x, y, isDark) {
            this.modules[y][x] = isDark;
            this.isFunction[y][x] = true;
        };

        QrCode.prototype.drawFormatBits = function(mask) {
            var data = (this.errorCorrectionLevel.formatBits << 3) | mask;
            var rem = data;
            for (var i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537);
            var bits = ((data << 10) | rem) ^ 0x5412;
            for (var i = 0; i <= 5; i++) this.setModule(8, i, ((bits >>> i) & 1) !== 0);
            this.setModule(8, 7, ((bits >>> 6) & 1) !== 0);
            this.setModule(8, 8, ((bits >>> 7) & 1) !== 0);
            this.setModule(7, 8, ((bits >>> 8) & 1) !== 0);
            for (var i = 9; i < 15; i++) this.setModule(14 - i, 8, ((bits >>> i) & 1) !== 0);

            for (var i = 0; i <= 7; i++) this.setModule(this.size - 1 - i, 8, ((bits >>> i) & 1) !== 0);
            for (var i = 8; i < 15; i++) this.setModule(8, this.size - 15 + i, ((bits >>> i) & 1) !== 0);
            this.setModule(8, this.size - 8, true);
        };

        QrCode.prototype.drawVersion = function() {
            if (this.version < 7) return;
            var rem = this.version;
            for (var i = 0; i < 12; i++) rem = (rem << 1) ^ ((rem >>> 11) * 0x1F25);
            var bits = (this.version << 12) | rem;
            for (var i = 0; i < 18; i++) {
                var bit = ((bits >>> i) & 1) !== 0;
                var a = this.size - 11 + (i % 3);
                var b = Math.floor(i / 3);
                this.setModule(a, b, bit);
                this.setModule(b, a, bit);
            }
        };

        QrCode.prototype.setModule = function(x, y, isDark) {
            this.modules[y][x] = isDark;
        };

        QrCode.prototype.drawCodewords = function(data) {
            var i = 0;
            for (var right = this.size - 1; right >= 1; right -= 2) {
                if (right === 6) right = 5;
                for (var vert = 0; vert < this.size; vert++) {
                    for (var j = 0; j < 2; j++) {
                        var x = right - j;
                        var upward = ((right + 1) & 2) === 0;
                        var y = upward ? this.size - 1 - vert : vert;
                        if (!this.isFunction[y][x] && i < data.length * 8) {
                            this.modules[y][x] = ((data[i >>> 3] >>> (7 - (i & 7))) & 1) !== 0;
                            i++;
                        }
                    }
                }
            }
        };

        QrCode.prototype.applyMask = function(mask) {
            for (var y = 0; y < this.size; y++) {
                for (var x = 0; x < this.size; x++) {
                    if (this.isFunction[y][x]) continue;
                    var invert = false;
                    switch (mask) {
                        case 0: invert = (x + y) % 2 === 0; break;
                        case 1: invert = y % 2 === 0; break;
                        case 2: invert = x % 3 === 0; break;
                        case 3: invert = (x + y) % 3 === 0; break;
                        case 4: invert = (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0; break;
                        case 5: invert = ((x * y) % 2) + ((x * y) % 3) === 0; break;
                        case 6: invert = (((x * y) % 2) + ((x * y) % 3)) % 2 === 0; break;
                        case 7: invert = (((x + y) % 2) + ((x * y) % 3)) % 2 === 0; break;
                    }
                    if (invert) this.modules[y][x] = !this.modules[y][x];
                }
            }
        };

        QrCode.prototype.getPenaltyScore = function() {
            var penalty = 0;
            // Horizontal and vertical runs
            for (var y = 0; y < this.size; y++) {
                var runColor = false, runLen = 0;
                for (var x = 0; x < this.size; x++) {
                    if (this.modules[y][x] === runColor) {
                        runLen++;
                        if (runLen === 5) penalty += 3;
                        else if (runLen > 5) penalty++;
                    } else {
                        runColor = this.modules[y][x];
                        runLen = 1;
                    }
                }
            }
            for (var x = 0; x < this.size; x++) {
                var runColor = false, runLen = 0;
                for (var y = 0; y < this.size; y++) {
                    if (this.modules[y][x] === runColor) {
                        runLen++;
                        if (runLen === 5) penalty += 3;
                        else if (runLen > 5) penalty++;
                    } else {
                        runColor = this.modules[y][x];
                        runLen = 1;
                    }
                }
            }
            return penalty;
        };

        // Reed-Solomon Error Correction Code Calculation
        QrCode.prototype.addEccAndInterleave = function(data) {
            var ver = this.version;
            var ecc = this.errorCorrectionLevel;
            var numBlocks = QrCode.NUM_ERROR_CORRECTION_BLOCKS[ecc.ordinal][ver];
            var blockEccLen = QrCode.ECC_CODEWORDS_PER_BLOCK[ecc.ordinal][ver];
            var rawCodewords = Math.floor(QrCode.getNumRawDataModules(ver) / 8);
            var numShortBlocks = numBlocks - (rawCodewords % numBlocks);
            var shortBlockLen = Math.floor(rawCodewords / numBlocks);

            var blocks = [];
            var rsPoly = reedSolomonComputeDivisor(blockEccLen);
            for (var i = 0, k = 0; i < numBlocks; i++) {
                var datLen = shortBlockLen - blockEccLen + (i >= numShortBlocks ? 1 : 0);
                var dat = data.slice(k, k + datLen);
                k += datLen;
                var eccData = reedSolomonComputeRemainder(dat, rsPoly);
                blocks.push({ data: dat, ecc: eccData });
            }

            var result = [];
            for (var i = 0; i < shortBlockLen - blockEccLen + 1; i++) {
                for (var j = 0; j < numBlocks; j++) {
                    if (i < blocks[j].data.length) result.push(blocks[j].data[i]);
                }
            }
            for (var i = 0; i < blockEccLen; i++) {
                for (var j = 0; j < numBlocks; j++) {
                    result.push(blocks[j].ecc[i]);
                }
            }
            return result;
        };

        function reedSolomonComputeDivisor(degree) {
            var result = [];
            for (var i = 0; i < degree - 1; i++) result.push(0);
            result.push(1);
            var root = 1;
            for (var i = 0; i < degree; i++) {
                for (var j = 0; j < result.length; j++) {
                    result[j] = reedSolomonMultiply(result[j], root);
                    if (j + 1 < result.length) result[j] ^= result[j + 1];
                }
                root = reedSolomonMultiply(root, 2);
            }
            return result;
        }

        function reedSolomonComputeRemainder(data, divisor) {
            var result = [];
            for (var i = 0; i < divisor.length; i++) result.push(0);
            for (var i = 0; i < data.length; i++) {
                var factor = data[i] ^ result.shift();
                result.push(0);
                for (var j = 0; j < divisor.length; j++) {
                    result[j] ^= reedSolomonMultiply(divisor[j], factor);
                }
            }
            return result;
        }

        function reedSolomonMultiply(x, y) {
            var z = 0;
            for (var i = 7; i >= 0; i--) {
                z = (z << 1) ^ ((z >>> 7) * 0x11D);
                z ^= ((y >>> i) & 1) * x;
            }
            return z;
        }

        QrCode.getNumRawDataModules = function(ver) {
            var size = ver * 4 + 17;
            var num = size * size;
            num -= 64 * 3; // Finders
            num -= 15 * 2 + 1; // Timing
            num -= (size - 16) * 2;
            if (ver >= 2) {
                var numAlign = Math.floor(ver / 7) + 2;
                num -= (numAlign * numAlign - 3) * 25;
                num += (numAlign - 2) * 2 * 10;
            }
            if (ver >= 7) num -= 36;
            return num;
        };

        QrCode.getNumDataCodewords = function(ver, ecc) {
            return Math.floor(QrCode.getNumRawDataModules(ver) / 8) -
                QrCode.ECC_CODEWORDS_PER_BLOCK[ecc.ordinal][ver] *
                QrCode.NUM_ERROR_CORRECTION_BLOCKS[ecc.ordinal][ver];
        };

        QrCode.getAlignmentPatternPositions = function(ver) {
            if (ver === 1) return [];
            var num = Math.floor(ver / 7) + 2;
            var step = (ver === 32) ? 26 : Math.ceil((ver * 4 + 4) / (num * 2 - 2)) * 2;
            var result = [6];
            for (var pos = ver * 4 + 10; result.length < num; pos -= step) {
                result.splice(1, 0, pos);
            }
            return result;
        };

        QrCode.ECC_CODEWORDS_PER_BLOCK = [
            [-1, 7, 10, 15, 20, 26, 18, 20, 24, 30, 18, 20, 24, 26, 30, 22, 24, 28, 30, 28, 28, 28, 28, 30, 30, 26, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
            [-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26, 26, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28],
            [-1, 13, 22, 18, 26, 18, 24, 18, 22, 20, 24, 28, 26, 24, 20, 30, 24, 28, 28, 26, 30, 28, 30, 30, 30, 30, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
            [-1, 17, 28, 22, 16, 22, 28, 26, 26, 24, 28, 24, 28, 22, 24, 24, 30, 28, 28, 26, 28, 30, 24, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30]
        ];

        QrCode.NUM_ERROR_CORRECTION_BLOCKS = [
            [-1, 1, 1, 1, 1, 1, 2, 2, 2, 2, 4, 4, 4, 4, 4, 6, 6, 6, 6, 7, 8, 8, 9, 9, 10, 12, 12, 12, 13, 14, 15, 16, 17, 18, 19, 19, 20, 21, 22, 24, 25],
            [-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16, 17, 17, 18, 20, 21, 23, 25, 26, 28, 29, 31, 33, 35, 37, 38, 40, 43, 45, 47, 49],
            [-1, 1, 1, 2, 2, 4, 4, 6, 6, 8, 8, 8, 10, 12, 16, 12, 17, 16, 18, 21, 20, 23, 23, 25, 27, 29, 34, 34, 35, 38, 40, 43, 45, 48, 51, 53, 56, 59, 62, 65, 68],
            [-1, 1, 1, 2, 4, 4, 4, 5, 6, 8, 8, 11, 11, 16, 16, 18, 16, 19, 21, 25, 25, 25, 34, 30, 32, 35, 37, 40, 42, 45, 48, 51, 54, 57, 60, 63, 66, 70, 74, 77, 81]
        ];

        return QrCode;
    })();

    // Helper wrapper compatible with `new QRCode(el, options)`
    function QRCode(element, options) {
        this._el = typeof element === 'string' ? document.getElementById(element) : element;
        this._options = {
            width: 256,
            height: 256,
            colorDark: '#000000',
            colorLight: '#ffffff',
            correctLevel: 'M'
        };
        if (typeof options === 'string') {
            this._options.text = options;
        } else if (options) {
            for (var key in options) {
                if (key === 'correctLevel') {
                    var val = options[key];
                    this._options.correctLevel = (val === 1 || val === 'L') ? 'L' :
                                                (val === 0 || val === 'M') ? 'M' :
                                                (val === 3 || val === 'Q') ? 'Q' : 'H';
                } else {
                    this._options[key] = options[key];
                }
            }
        }
        if (this._options.text) {
            this.makeCode(this._options.text);
        }
    }

    QRCode.prototype.makeCode = function(text) {
        var qr = QrCode.encodeText(text, QrCode.Ecc[this._options.correctLevel || 'M']);
        this._el.innerHTML = '';
        var canvas = document.createElement('canvas');
        canvas.width = this._options.width;
        canvas.height = this._options.height;
        var ctx = canvas.getContext('2d');

        var scale = this._options.width / qr.size;
        ctx.fillStyle = this._options.colorLight;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.fillStyle = this._options.colorDark;
        for (var y = 0; y < qr.size; y++) {
            for (var x = 0; x < qr.size; x++) {
                if (qr.getModule(x, y)) {
                    var rx = Math.round(x * scale);
                    var ry = Math.round(y * scale);
                    var rw = Math.ceil((x + 1) * scale) - rx;
                    var rh = Math.ceil((y + 1) * scale) - ry;
                    ctx.fillRect(rx, ry, rw, rh);
                }
            }
        }
        this._el.appendChild(canvas);
        this._canvas = canvas;
    };

    QRCode.prototype.getCanvas = function() {
        return this._canvas;
    };

    window.QRCode = QRCode;
})(window);
